#include "profile.h"
#include <stdio.h>
#include <stdlib.h>
typedef struct Counts { size_t calls, reused, available, compiled; } Counts;
static Counts counts[4096];
void profile_call(MarimayBytecodeJitContext *context, size_t callee) {
    MarimayBytecodeJitActivation *a = context->activation;
    if (callee >= a->jit->function_count || callee >= 4096) abort();
    Counts *c = &counts[callee]; c->calls += 1;
    c->compiled += a->jit->functions[callee].code != NULL;
    if (a->stack->count < a->stack->capacity) {
        const MarimayBytecodeRunFrame *next = &a->stack->frames[a->stack->count];
        const MarimayBytecodeProgramFunction *functions = a->program->functions.data;
        c->available += 1;
        c->reused += next->function == &functions[callee] && next->roots_prepared;
    }
}
void profile_dump(MarimayBytecodeJit *jit) {
    if (!jit || !jit->state || !jit->state->activation.program) return;
    const MarimayBytecodeProgramFunction *f = jit->state->activation.program->functions.data;
    const MarimayBytecodeExecutionImage *image = jit->state->activation.image;
    fputs("JIT_CALLS {\"functions\":[", stderr);
    const char *comma = "";
    for (size_t i = 0; i < jit->function_count && i < 4096; ++i) {
        if (!counts[i].calls) continue;
        fprintf(stderr, "%s{\"id\":%zu,\"calls\":%zu,\"reused\":%zu,\"available\":%zu,\"compiled\":%zu,\"registers\":%zu,\"managed_registers\":%zu,\"parameters\":%zu,\"return_type\":%d,\"call_sites\":%zu,\"operations\":%zu,\"borrows_roots\":%s,\"code_bytes\":%zu}", comma,i,counts[i].calls,counts[i].reused,counts[i].available,counts[i].compiled,f[i].body.register_types.length,jit->functions[i].frame_layout.managed_count,f[i].body.parameter_count,(int)f[i].body.result_type,f[i].body.calls.length,image->functions[i].operation_count,image->functions[i].borrows_caller_roots?"true":"false",jit->functions[i].code_bytes);
        comma=",";
    }
    fputs("]}\n", stderr);
}

